package io.forgeloop.control.domain;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames="task_id")) public class TaskLease { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @OneToOne(optional=false) @JoinColumn(name="task_id") private DeliveryTask task; @ManyToOne(optional=false) private Runner runner; @Column(nullable=false,unique=true) private String nonceHash; @Column(nullable=false) private Instant expiresAt; private Instant acknowledgedAt; private Instant completedAt; protected TaskLease(){} public TaskLease(DeliveryTask task,Runner runner,String nonceHash,Instant expiresAt){this.task=task;this.runner=runner;this.nonceHash=nonceHash;this.expiresAt=expiresAt;} public boolean active(){return completedAt==null&&Instant.now().isBefore(expiresAt);} public boolean belongsTo(String runnerId){return runner.getId().equals(runnerId);} public boolean matchesNonceHash(String hash){return java.security.MessageDigest.isEqual(nonceHash.getBytes(java.nio.charset.StandardCharsets.US_ASCII),hash.getBytes(java.nio.charset.StandardCharsets.US_ASCII));} public void acknowledge(){if(!active())throw new IllegalStateException("Lease is expired");acknowledgedAt=Instant.now();} public String getId(){return id;} public String getTaskId(){return task.getId();} public String getRunnerId(){return runner.getId();} public String getExpiresAt(){return expiresAt.toString();} public boolean isAcknowledged(){return acknowledgedAt!=null;} }
